<?php
require_once __DIR__ . '/../../includes/db.php';require_once __DIR__ . '/../includes/auth.php';require_once __DIR__ . '/../includes/business_helpers.php';require_login();
if(!isset($_GET['car_id'])||!is_numeric($_GET['car_id'])){set_flash('error','Car ID missing.');redirect_to('backend/cars/list.php');}$car_id=(int)$_GET['car_id'];$car_q=$conn->prepare('SELECT id,car_name,status FROM cars WHERE id=?');$car_q->bind_param('i',$car_id);$car_q->execute();$car=$car_q->get_result()->fetch_assoc();if(!$car){set_flash('error','Car not found.');redirect_to('backend/cars/list.php');}if($car['status']==='SOLD'){set_flash('error','Cannot add costs to a sold car.');redirect_to('backend/cars/view.php?id='.$car_id);}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$cost_type=trim($_POST['cost_type']??'');$description=trim($_POST['description']??'');$amount=(float)($_POST['amount']??0);$cost_date=$_POST['cost_date']??'';if($cost_type===''||$amount<=0||$cost_date===''){$error='Please fill all required fields correctly.';}else{$stmt=$conn->prepare('INSERT INTO car_costs (car_id,cost_type,description,amount,cost_date) VALUES (?,?,?,?,?)');$stmt->bind_param('issds',$car_id,$cost_type,$description,$amount,$cost_date);$stmt->execute();$costId=(int)$stmt->insert_id;car_sales_audit($conn,'CREATE','car_cost',$costId,'Added vehicle cost '.money($amount).' ('.$cost_type.').',null,['car_id'=>$car_id,'cost_type'=>$cost_type,'amount'=>$amount,'cost_date'=>$cost_date]);set_flash('success','Cost added successfully.');redirect_to('backend/cars/view.php?id='.$car_id);}}
$page_title='Add Cost';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';
?>
<div class="content-page"><h1 class="page-title">Add Cost</h1><div class="card form-card"><p><strong>Car:</strong> <?=e($car['car_name'])?></p><?php if($error):?><div class="flash-message error" style="position:static;margin-bottom:16px;"><?=e($error)?></div><?php endif;?><form method="post"><div class="form-group"><label>Cost Type *</label><select name="cost_type" required><option value="">-- Select Cost Type --</option><option>Repair</option><option>Service</option><option>Spare Parts</option><option>Transport</option><option>Registration</option><option>Import</option><option>Clearing</option><option>Other</option></select></div><div class="form-group"><label>Description</label><textarea name="description" rows="3"></textarea></div><div class="form-row"><div class="form-group"><label>Amount *</label><input type="number" name="amount" step="0.01" required></div><div class="form-group"><label>Cost Date *</label><input type="date" name="cost_date" required></div></div><button class="btn btn-green" type="submit">Save Cost</button><a class="btn btn-dark" href="../cars/view.php?id=<?=$car_id?>">Cancel</a></form></div></div><?php include __DIR__.'/../includes/footer.php'; ?>
